css:
/* Keep T3 Code UI chrome in JetBrains Mono even when Interface Font is set to Noto Sans (for HTML previews). */
:root {
  --font-sans: "JetBrainsMono Nerd Font", ui-sans-serif, system-ui, sans-serif !important;
}

/* Markdown previews (file viewer, attachment previews, etc.) use normal sans-serif. */
.chat-markdown {
  font-family: "Noto Sans", ui-sans-serif, system-ui, sans-serif !important;
}

/* Enlarge chat messages without changing the rest of the UI. */
[data-message-role="assistant"] .chat-markdown,
[data-user-message-bubble] {
  font-size: 17px !important;
  line-height: 1.6;
  font-family: "Noto Sans", ui-sans-serif, system-ui, sans-serif !important;
}

/* Tokyo Night colours for chat code blocks only. */

/* Comments */
.chat-markdown pre [style*="#737373" i],
.chat-markdown pre [style*="115, 115, 115"] {
  color: #565f89 !important;
}

/* Keywords */
.chat-markdown pre [style*="#ff678d" i],
.chat-markdown pre [style*="255, 103, 141"] {
  color: #bb9af7 !important;
}

/* Strings */
.chat-markdown pre [style*="#5ecc71" i],
.chat-markdown pre [style*="94, 204, 113"] {
  color: #9ece6a !important;
}

/* Functions */
.chat-markdown pre [style*="#9d6afb" i],
.chat-markdown pre [style*="157, 106, 251"] {
  color: #7aa2f7 !important;
}

/* Types and classes */
.chat-markdown pre [style*="#d568ea" i],
.chat-markdown pre [style*="213, 104, 234"] {
  color: #2ac3de !important;
}

/* Numbers and booleans */
.chat-markdown pre [style*="#68cdf2" i],
.chat-markdown pre [style*="104, 205, 242"] {
  color: #ff9e64 !important;
}

/* Constants */
.chat-markdown pre [style*="#ffd452" i],
.chat-markdown pre [style*="255, 212, 82"],
.chat-markdown pre [style*="#ffab16" i],
.chat-markdown pre [style*="255, 171, 22"] {
  color: #ff9e64 !important;
}

/* Variables and properties */
.chat-markdown pre [style*="#ffa359" i],
.chat-markdown pre [style*="255, 163, 89"] {
  color: #c0caf5 !important;
}

/* Operators */
.chat-markdown pre [style*="#08c0ef" i],
.chat-markdown pre [style*="8, 192, 239"] {
  color: #89ddff !important;
}

/* Punctuation */
.chat-markdown pre [style*="#636363" i],
.chat-markdown pre [style*="99, 99, 99"] {
  color: #a9b1d6 !important;
}
